/**
 * Demo fixtures — SYNTHETIC data only, loaded into the signed-in user's own account and always flagged
 * `is_demo = true`. Demo reports are never compared with real reports (see compare.ts) and are labelled in the UI.
 *
 * Sources (see /fixtures):
 *  - demo_2026-08.pdf          = fixtures/sample-reports/report_patient_3.pdf (supplied sample, "unstable" profile)
 *  - demo_history_2026-06.pdf  = generated by fixtures/generate_demo_history.py (same layout, 30 days)
 *  - demo_history_2026-07.pdf  = generated by fixtures/generate_demo_history.py (14 days → limited comparison)
 *  - HbA1c 7.4 % on 2026-08-02 = fixtures/labs/final_patients_with_DC_labs.xlsx row for patient_id 3
 * Every report goes through the real upload → extraction pipeline; nothing here is hard-coded into results.
 */
import * as api from './api';

export const DEMO_REPORTS = [
  { file: 'demo_history_2026-06.pdf', name: 'Demo — AGP June 2026.pdf' },
  { file: 'demo_history_2026-07.pdf', name: 'Demo — AGP July 2026 (14 days).pdf' },
  { file: 'demo_2026-08.pdf', name: 'Demo — AGP August 2026.pdf' },
];
export const DEMO_LAB = { value: 7.4, measured_on: '2026-08-02', note: 'Synthetic demo value (fixtures/labs/final_patients_with_DC_labs.xlsx, patient 3)' };

export async function loadDemoData(userId: string, onProgress: (i: number, n: number) => void): Promise<void> {
  await api.addLab(DEMO_LAB.value, DEMO_LAB.measured_on, DEMO_LAB.note, true);
  for (let i = 0; i < DEMO_REPORTS.length; i++) {
    onProgress(i + 1, DEMO_REPORTS.length);
    const d = DEMO_REPORTS[i];
    const res = await fetch(`${import.meta.env.BASE_URL}demo/${d.file}`);
    if (!res.ok) throw new Error(`Missing demo file ${d.file}`);
    const blob = await res.blob();
    const id = await api.uploadReport(userId, new Blob([blob], { type: 'application/pdf' }), d.name, true);
    // Process in order so each report sees the earlier ones for comparison-based questions.
    await api.processReport(id);
  }
}
